// ════════════════════════════════════════════════════════════════════════════
// gen-skills.mjs (Epic 25, Story 25.1, AC 25.1.2)
//
// Generates the installable `skills/` directory from the prompt content
// authored ONCE in `packages/{ops,dev,interop,admin}-mcp/src/prompts/*.ts`
// (single source of truth per spec `03-skills-prompts-pack.md` §3). Every
// generated file carries a DO-NOT-EDIT header (Rule #18).
//
// Each skill's body is the text its prompt renders. Its `description` and its tool preset (the
// `metadata` `iris-tools-preset`) come from the prompt's own `skill: { description, preset }` field,
// which only this generator and `validate:prompts` read (AD-28). A prompt without a valid `skill`
// field stops the run (exit 1, in `--check` too) before anything is written. The rendering lives in
// scripts/lib/workflow-skills.mjs.
//
// UNLIKE `scripts/gen-governance-baseline.mjs`, `skills/` is NOT a frozen
// artifact (Rule #23/#25 do not apply here) — the default (no-flag) mode
// WRITES. `--check` is the CI / no-write verification mode (Rule #25
// shape): it re-derives the expected content from source and diffs against
// the on-disk `skills/` tree WITHOUT writing, failing (exit 1) on ANY drift
// — including a hand-edited generated file, a missing generated file, or a
// stale file left over from a removed prompt.
//
// USAGE:
//   node scripts/gen-skills.mjs            Regenerate skills/ from source (writes).
//   node scripts/gen-skills.mjs --check    No-write drift verification (CI-safe).
//
//   npm: `pnpm gen:skills` / `pnpm gen:skills:check`
//
// `skills/` is owned entirely by this generator. Hand-authored pack sources live in
// `skills-pack-src/` and reach the skills pack through `pnpm gen:pack`, never through `skills/`.
//
// Requires a prior `pnpm turbo run build` (imports each package's BUILT
// dist/prompts/index.js — see scripts/lib/prompt-catalog.mjs).
// ════════════════════════════════════════════════════════════════════════════

import { resolve, dirname } from 'path';
import { fileURLToPath } from 'url';
import { loadAllPrompts } from './lib/prompt-catalog.mjs';
import { diffTree, writeTree } from './lib/generated-tree.mjs';
import { promptSkillProblems, renderWorkflowSkill } from './lib/workflow-skills.mjs';

const __dirname = dirname(fileURLToPath(import.meta.url));
const root = resolve(__dirname, '..');

const argv = process.argv.slice(2);
const CHECK_MODE = argv.includes('--check');

const skillsDir = resolve(root, 'skills');

/** DO-NOT-EDIT header text shared by every generated file (Rule #18). */
function doNotEditHeader(sourceNote) {
  return (
    `<!-- DO NOT EDIT — generated by scripts/gen-skills.mjs from ${sourceNote}.\n` +
    `     Regenerate via: pnpm gen:skills -->\n`
  );
}

/** Render `skills/README.md`, the installable-skills install guide (contributor-facing, not agent content). */
function renderReadme(entries) {
  const header = doNotEditHeader('the registered PromptDefinitions across packages/*/src/prompts/*.ts');
  const rows = entries
    .map(({ pkg, prompt }) => `| \`${prompt.name}\` | ${pkg} | \`${prompt.skill.preset}\` | ${prompt.skill.description} |`)
    .join('\n');
  return (
    `${header}\n` +
    `# IRIS MCP Agent Skills Pack\n\n` +
    `This directory is **generated** from the suite's MCP \`prompts\` capability (Epic 25). Each skill's ` +
    `body is the text \`prompts/get\` renders for the prompt of the same name. Its \`description\` is the ` +
    `prompt's separate model-invocation description, and \`metadata.iris-tools-preset\` is its tool preset; ` +
    `both are set in the prompt's \`skill\` field in \`packages/<server>/src/prompts/\`. The skills pack ` +
    `catalog, \`packages/client-config/skills-pack/README.md\`, lists these skills with the knowledge ` +
    `skills and the always-on rule.\n\n` +
    `## Installation\n\n` +
    `Copy the skill directories you want into your project's \`.claude/skills/\` directory (or point ` +
    `your client's skill-loader configuration at this \`skills/\` directory directly):\n\n` +
    `\`\`\`bash\ncp -r skills/<skill-name> /path/to/your/project/.claude/skills/\n\`\`\`\n\n` +
    `Each skill is a self-contained \`SKILL.md\` with YAML frontmatter (\`name\`, \`description\`, \`metadata\`) ` +
    `followed by the workflow instructions — the exact tool sequence, argument names, and safety notes ` +
    `an MCP client should follow. Tool names referenced in every skill are validated against the live ` +
    `tool catalog by \`scripts/validate-prompts.mjs\` (wired into the default test suite), so a renamed ` +
    `or removed tool breaks CI rather than shipping a broken skill.\n\n` +
    `## Available Skills\n\n` +
    `| Skill | Server | Tool preset | Description |\n` +
    `|---|---|---|---|\n` +
    `${rows}\n\n` +
    `Prefer calling these workflows via the MCP \`prompts\` capability directly (\`prompts/get\`) when ` +
    `your client supports it — the skill files here are a convenience export for clients that only load ` +
    `local skill directories.\n`
  );
}

/** Every generated file, relative-to-`skills/` path -> expected content. */
async function computeExpectedFiles() {
  const entries = await loadAllPrompts(root);

  // A prompt that cannot be rendered as a skill stops the run, in check mode too, before anything is written.
  const skillProblems = entries.flatMap(({ pkg, prompt }) =>
    promptSkillProblems(prompt).map((message) => `gen-skills: prompt ${pkg}/${prompt.name} ${message}`),
  );
  if (skillProblems.length > 0) {
    for (const line of skillProblems) console.error(line);
    process.exit(1);
  }

  const files = new Map();
  for (const { prompt } of entries) {
    files.set(`${prompt.name}/SKILL.md`, renderWorkflowSkill(prompt));
  }
  files.set('README.md', renderReadme(entries));
  return { entries, files };
}

const { entries, files } = await computeExpectedFiles();

if (CHECK_MODE) {
  // Any on-disk file under skills/ that is not an expected generated file is flagged: a whole stale
  // skill directory (no source prompt) and a stray file inside an otherwise-valid skill directory alike.
  const { missing, drift, stray } = diffTree(files, skillsDir);

  for (const rel of missing) {
    console.error(`gen-skills --check: MISSING generated file: skills/${rel}`);
  }
  for (const rel of drift) {
    console.error(
      `gen-skills --check: DRIFT in skills/${rel} (hand-edited, or source changed without regenerating).`,
    );
  }
  for (const rel of stray) {
    console.error(`gen-skills --check: STRAY/STALE generated file (no source prompt): skills/${rel}`);
  }

  if (missing.length + drift.length + stray.length > 0) {
    console.error('');
    console.error('Run "pnpm gen:skills" to regenerate skills/ from source, then commit the result.');
    process.exit(1);
  }

  console.log(`gen-skills --check: OK — ${files.size} generated file(s) match source, no drift.`);
  process.exit(0);
}

// ── Write mode (default) ─────────────────────────────────────────────────
// Removes every file under skills/ that is not expected (a leftover SKILL.md from a removed prompt, or a
// hand-added file), then writes every expected file, so `--check` never flags a leftover this generator
// could have removed.
for (const rel of writeTree(files, skillsDir)) {
  console.log(`gen-skills: removing stray/stale generated file: skills/${rel}`);
}

console.log(`Generated ${files.size} file(s) under skills/ from ${entries.length} prompt(s).`);
